import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void cross_entropy_kernel(const half* __restrict__ logits,
                                     const long long* __restrict__ targets,
                                     float* __restrict__ loss_sum,
                                     int batch,
                                     int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch) return;

    const half* sample = logits + idx * num_classes;
    int target = static_cast<int>(targets[idx]);

    // Find max for numerical stability
    float max_val = __half2float(sample[0]);
    for (int c = 1; c < num_classes; ++c) {
        float v = __half2float(sample[c]);
        if (v > max_val) max_val = v;
    }

    // Compute sum of exp(logit - max)
    float sum_exp = 0.0f;
    for (int c = 0; c < num_classes; ++c) {
        float v = __half2float(sample[c]) - max_val;
        sum_exp += expf(v);
    }

    float log_sum_exp = max_val + logf(sum_exp);
    float logit_target = __half2float(sample[target]);

    float loss = -(logit_target - log_sum_exp);

    atomicAdd(loss_sum, loss);
}

torch::Tensor cross_entropy_cuda(torch::Tensor logits, torch::Tensor targets) {
    const int batch = logits.size(0);
    const int num_classes = logits.size(1);

    auto loss_sum = torch::zeros({1},
                                 torch::device(logits.device()).dtype(torch::kFloat32));

    const int threads = 256;
    const int blocks = (batch + threads - 1) / threads;

    // Launch kernel (logits are expected to be fp16)
    cross_entropy_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(logits.data_ptr()),
        targets.data_ptr<long long>(),
        loss_sum.data_ptr<float>(),
        batch,
        num_classes
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    // Mean reduction
    auto loss = loss_sum / static_cast<float>(batch);
    return loss.to(logits.dtype());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cross_entropy_cuda", &cross_entropy_cuda, "Cross‑entropy forward (fp16) CUDA");
}
'''

# Compile the inline CUDA extension
cross_entropy_ext = load_inline(
    name='cross_entropy_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['cross_entropy_cuda'],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for torch.nn.functional.cross_entropy
    (expects fp16 predictions and int64 targets, returns fp16 scalar loss).
    """
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        # predictions: (B, C) fp16, targets: (B,) int64
        return cross_entropy_ext.cross_entropy_cuda(predictions, targets)

def get_inputs():
    return [
        torch.rand(32768, 4096, dtype=torch.float16, device='cuda'),
        torch.randint(0, 4096, (32768,), dtype=torch.long, device='cuda')
    ]

